// Cable bridge - a block with two semicircular tunnels along Y at floor level
// Units: mm. Print orientation: base on XY plane, building up +Z.

// ---------------- Parameters ----------------
block_len   = 80;    // block length along X
block_wid   = 40;    // block width along Y
block_ht    = 12;    // block height along Z

tunnel_d    = 10;    // diameter of each semicircular tunnel (cylinder along Y)
tunnel_sep  = 16;    // centre-to-centre spacing of the two tunnels along X
tunnel_z    = 0;     // height of tunnel axes (floor level)

eps         = 0.5;   // overshoot for clean boolean cuts
$fn         = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: half-cylinders whose axes lie along Y at z = 0.
    // Because the axes are at floor level, each cylinder is split by the bed:
    // the lower half is below z = 0 and the upper half runs through the block.
    // The visible tunnel is therefore a D-shaped prism (cylinder cut by a plane),
    // extended past the block faces along X so the cut reaches through.
    for (i = [-1, 1]) {
        x_c = -tunnel_sep/2 + i * tunnel_sep/2;   // tunnel axis X position
        translate([x_c - eps, -block_wid/2 - eps, tunnel_z])
            linear_extrude(height = block_wid + 2*eps)
                cylinder(d = tunnel_d, h = block_ht + 2*eps, $fn = 96);
    }
}
```

